280→func TestParseHookEvent_AllHookTypes(t *testing.T) {
281→	t.Parallel()
282→
283→	testCases := []struct {
284→		hookName      string
285→		expectedType  agent.EventType
286→		expectNil     bool
287→		inputTemplate string
288→	}{
289→		{
290→			hookName:      HookNameSessionStart,
291→			expectedType:  agent.SessionStart,
292→			inputTemplate: `{"session_id": "s1", "transcript_path": "/t"}`,
293→		},
294→		{
295→			hookName:      HookNameBeforeSubmitPrompt,
296→			expectedType:  agent.TurnStart,
297→			inputTemplate: `{"session_id": "s2", "transcript_path": "/t", "prompt": "hi"}`,
298→		},
299→		{
300→			hookName:      HookNameStop,
301→			expectedType:  agent.TurnEnd,
302→			inputTemplate: `{"session_id": "s3", "transcript_path": "/t"}`,
303→		},
304→		{
305→			hookName:      HookNameSessionEnd,
306→			expectedType:  agent.SessionEnd,
307→			inputTemplate: `{"session_id": "s4", "transcript_path": "/t"}`,
308→		},
309→		{
310→			hookName:      HookNameSubagentStart,
311→			expectedType:  agent.SubagentStart,
312→			inputTemplate: `{"conversation_id": "s5", "transcript_path": "/t", "subagent_id": "sub1", "task": "do something"}`,
313→		},
314→		{
315→			hookName:      HookNameSubagentStop,
316→			expectedType:  agent.SubagentEnd,
317→			inputTemplate: `{"conversation_id": "s6", "transcript_path": "/t", "subagent_id": "sub2", "task": "do something"}`,
318→		},
319→	}
320→
321→	for _, tc := range testCases {
322→		t.Run(tc.hookName, func(t *testing.T) {
323→			t.Parallel()
324→
325→			ag := &CursorAgent{}
326→			event, err := ag.ParseHookEvent(context.Background(), tc.hookName, strings.NewReader(tc.inputTemplate))
327→
328→			if err != nil {
329→				t.Fatalf("unexpected error: %v", err)
330→			}
331→
332→			if tc.expectNil {
333→				if event != nil {
334→					t.Errorf("expected nil event, got %+v", event)
335→				}
336→				return
337→			}
338→
339→			if event == nil {
340→				t.Fatal("expected event, got nil")
341→			}
342→			if event.Type != tc.expectedType {
343→				t.Errorf("expected event type %v, got %v", tc.expectedType, event.Type)
344→			}
345→		})
346→	}
347→}
