 14→// sampleTranscriptLines returns JSONL lines matching real Cursor transcript format.
 15→// Based on an actual Cursor session: uses "role" (not "type"), wraps user text
 16→// in <user_query> tags, and contains no tool_use blocks.
 17→func sampleTranscriptLines() []string {
 18→	return []string{
 19→		`{"role":"user","message":{"content":[{"type":"text","text":"<user_query>\nhello\n</user_query>"}]}}`,
 20→		`{"role":"assistant","message":{"content":[{"type":"text","text":"Hi there!"}]}}`,
 21→		`{"role":"user","message":{"content":[{"type":"text","text":"<user_query>\nadd 'one' to a file and commit\n</user_query>"}]}}`,
 22→		`{"role":"assistant","message":{"content":[{"type":"text","text":"Created one.txt with one and committed."}]}}`,
 23→	}
 24→}
 25→
 26→func writeSampleTranscript(t *testing.T, dir string) string {
 27→	t.Helper()
 28→	path := filepath.Join(dir, "transcript.jsonl")
 29→	content := strings.Join(sampleTranscriptLines(), "\n") + "\n"
 30→	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
 31→		t.Fatalf("failed to write sample transcript: %v", err)
 32→	}
 33→	return path
 34→}
