 97→// JoinAgentNames joins agent names into a comma-separated string.
 98→func JoinAgentNames(names []agent.AgentName) string {
 99→	strs := make([]string, len(names))
100→	for i, n := range names {
101→		strs[i] = string(n)
102→	}
103→	return strings.Join(strs, ",")
104→}
