  1→package agents
  2→
  3→import (
  4→	"context"
  5→	"errors"
  6→	"fmt"
  7→	"os"
  8→	"os/exec"
  9→	"strings"
 10→	"time"
 11→)
 12→
 13→type openCodeAgent struct {
 14→	model   string
 15→	timeout time.Duration
 16→}
 17→
 18→func init() {
 19→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "opencode" {
 20→		return
 21→	}
 22→	if _, err := exec.LookPath("opencode"); err != nil {
 23→		return
 24→	}
 25→	model := os.Getenv("E2E_OPENCODE_MODEL")
 26→	if model == "" {
 27→		model = "anthropic/claude-haiku-4-5"
 28→	}
 29→	Register(&openCodeAgent{model: model, timeout: 2 * time.Minute})
 30→}
 31→
 32→func (a *openCodeAgent) Name() string               { return "opencode" }
 33→func (a *openCodeAgent) Binary() string             { return "opencode" }
 34→func (a *openCodeAgent) EntireAgent() string        { return "opencode" }
 35→func (a *openCodeAgent) PromptPattern() string      { return `(Ask anything|▣)` }
 36→func (a *openCodeAgent) TimeoutMultiplier() float64 { return 2.0 }
 37→
 38→func (a *openCodeAgent) IsTransientError(out Output, err error) bool {
 39→	if err == nil {
 40→		return false
 41→	}
 42→	combined := out.Stdout + out.Stderr
 43→	transientPatterns := []string{
 44→		"overloaded",
 45→		"rate limit",
 46→		"529",
 47→		"503",
 48→		"ECONNRESET",
 49→		"ETIMEDOUT",
 50→		"Token refresh failed",
 51→	}
 52→	for _, p := range transientPatterns {
 53→		if strings.Contains(combined, p) {
 54→			return true
 55→		}
 56→	}
 57→	return false
 58→}
 59→
 60→// detectStderrError checks stderr for error patterns that indicate the agent
 61→// failed despite exiting 0. Returns the first matching line, or "".
 62→func detectStderrError(stderr string) string {
 63→	for _, line := range strings.Split(stderr, "\n") {
 64→		trimmed := strings.TrimSpace(line)
 65→		if strings.HasPrefix(trimmed, "Error:") || strings.HasPrefix(trimmed, "error:") {
 66→			return trimmed
 67→		}
 68→	}
 69→	return ""
 70→}
 71→
 72→func (a *openCodeAgent) Bootstrap() error {
 73→	// opencode has first-run DB migration + node_modules resolution that
 74→	// races with parallel test execution (upstream issue #6935).
 75→	// Run a trivial prompt to force full initialization before tests.
 76→	for i := range 3 {
 77→		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 78→		cmd := exec.CommandContext(ctx, a.Binary(), "run", "--model", a.model, "say hi")
 79→		cmd.Env = os.Environ()
 80→		out, err := cmd.CombinedOutput()
 81→		cancel()
 82→		if err == nil {
 83→			return nil
 84→		}
 85→		if i < 2 {
 86→			fmt.Fprintf(os.Stderr, "opencode warmup attempt %d failed: %s\n%s\n", i+1, err, out)
 87→			time.Sleep(5 * time.Second)
 88→		}
 89→	}
 90→	// Non-fatal: warmup failure shouldn't block tests entirely.
 91→	fmt.Fprintln(os.Stderr, "opencode warmup failed after 3 attempts, proceeding anyway")
 92→	return nil
 93→}
 94→
 95→func (a *openCodeAgent) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 96→	cfg := &runConfig{}
 97→	for _, o := range opts {
 98→		o(cfg)
 99→	}
100→
101→	model := a.model
102→	if cfg.Model != "" {
103→		model = cfg.Model
104→	}
105→
106→	args := []string{"run"}
107→	if model != "" {
108→		args = append(args, "--model", model)
109→	}
110→	args = append(args, prompt)
111→
112→	timeout := a.timeout
113→	if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
114→		if parsed, err := time.ParseDuration(envTimeout); err == nil {
115→			timeout = parsed
116→		}
117→	}
118→
119→	ctx, cancel := context.WithTimeout(ctx, timeout)
120→	defer cancel()
121→
122→	cmd := exec.CommandContext(ctx, a.Binary(), args...)
123→	cmd.Dir = dir
124→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
125→
126→	var stdout, stderr strings.Builder
127→	cmd.Stdout = &stdout
128→	cmd.Stderr = &stderr
129→
130→	err := cmd.Run()
131→	out := Output{
132→		Command: a.Binary() + " " + strings.Join(args, " "),
133→		Stdout:  stdout.String(),
134→		Stderr:  stderr.String(),
135→	}
136→
137→	if err != nil {
138→		var exitErr *exec.ExitError
139→		if errors.As(err, &exitErr) {
140→			out.ExitCode = exitErr.ExitCode()
141→		} else {
142→			out.ExitCode = -1
143→		}
144→		return out, err
145→	}
146→
147→	// OpenCode sometimes exits 0 despite fatal errors (auth failures, etc.)
148→	// that appear only in stderr. Detect these and return an error so the
149→	// test framework can retry or fail early.
150→	if msg := detectStderrError(stderr.String()); msg != "" {
151→		return out, fmt.Errorf("opencode exited 0 but stderr indicates failure: %s", msg)
152→	}
153→
154→	return out, nil
155→}
156→
157→func (a *openCodeAgent) StartSession(ctx context.Context, dir string) (Session, error) {
158→	// opencode's TUI occasionally fails to render on CI (empty pane).
159→	// Retry once if the first attempt produces no output at all.
160→	var s *TmuxSession
161→	var lastErr error
162→	for attempt := range 2 {
163→		name := fmt.Sprintf("opencode-test-%d", time.Now().UnixNano())
164→		var err error
165→		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", a.Binary(), "--model", a.model)
166→		if err != nil {
167→			return nil, err
168→		}
169→
170→		// Wait for TUI to be ready (input area with placeholder text).
171→		if _, err := s.WaitFor(`Ask anything`, 15*time.Second); err != nil {
172→			content := s.Capture()
173→			_ = s.Close()
174→			if strings.TrimSpace(content) == "" && attempt == 0 {
175→				lastErr = err
176→				continue
177→			}
178→			return nil, fmt.Errorf("waiting for startup: %w", err)
179→		}
180→		s.stableAtSend = ""
181→		return s, nil
182→	}
183→	return nil, fmt.Errorf("opencode TUI failed to start after retry: %w", lastErr)
184→}
